_N = [
("def","definition","critère",2,0,IDSA,"L'impétigo est une infection bactérienne superficielle de l'épiderme ; le furoncle infecte un follicule pileux et l'abcès forme une collection de pus dans le derme ou l'hypoderme."),
("epi","epidemiology","terrain particulier",1,0,EXP,"L'impétigo touche surtout le jeune enfant en collectivité et se transmet par contact ; un eczéma, une gale ou des piqûres grattées favorisent l'impétiginisation."),
("germes","basicSciences","mécanisme",2,0,IDSA,"Staphylococcus aureus cause la majorité des impétigos et presque tous les furoncles et abcès ; Streptococcus pyogenes cause ou accompagne une partie des impétigos ; la toxine exfoliative de S. aureus explique les bulles."),
("pvl","basicSciences","mécanisme",1,0,EXP,"Les souches de S. aureus productrices de leucocidine de Panton-Valentine causent des furoncles récidivants, nécrotiques et transmis dans la famille."),
("contage","anamnesis","critère",1,0,EXP,"On recherche des cas dans la famille ou la collectivité, une dermatose préexistante et, pour les furoncles récidivants, un contage familial ou sportif."),
("croutes","clinicalExam","signe",3,0,IDSA+" ; "+EXP,"L'impétigo non bulleux débute par une vésicule ou une pustule fugace, puis forme des croûtes jaune miel, dites mélicériques, souvent autour du nez et de la bouche."),
("bulle","clinicalExam","signe",1,0,IDSA,"L'impétigo bulleux, plus fréquent chez le nourrisson, forme des bulles flasques qui laissent des érosions à collerette."),
("abces","clinicalExam","signe",2,0,IDSA,"L'abcès se présente comme un nodule rouge, chaud, douloureux et fluctuant ; le furoncle est centré sur un poil et l'anthrax réunit plusieurs furoncles."),
("sirs","presumptionRedFlags","seuil",2,0,IDSA,"Une température au-dessus de 38 °C ou sous 36 °C, une fréquence cardiaque au-dessus de 90/min, une fréquence respiratoire au-dessus de 24/min ou des leucocytes au-dessus de 12 G/l ou sous 4 G/l signent une réponse systémique qui impose un antibiotique."),
("ecthyma","presumptionRedFlags","diagnostic différentiel",1,0,IDSA,"L'ecthyma, forme creusante de l'impétigo, exige un traitement oral ; une douleur disproportionnée fait craindre une infection nécrosante, urgence chirurgicale."),
("diagclin","workupGoldStandard","examen",1,0,IDSA,"Le diagnostic de l'impétigo et du furoncle reste clinique ; un impétigo simple ne demande pas de prélèvement."),
("culture","workupAlternatives","examen",2,0,IDSA,"On cultive le pus d'un abcès drainé, d'un abcès récidivant, d'un échec ou d'une forme étendue, pour obtenir l'antibiogramme et repérer un S. aureus résistant à la méticilline."),
("herpes","positiveDiagnosis","diagnostic différentiel",1,0,EXP,"Des vésicules groupées, ombiliquées et douloureuses sur un eczéma évoquent un eczéma herpétiforme, qui demande un antiviral et non un antibiotique."),
("topique","acuteManagement","décision",3,0,IDSA+" ; "+AIPS,"Un impétigo limité se traite localement, après nettoyage et décroûtage doux, par un antibiotique topique comme la mupirocine deux fois par jour pendant 5 jours (acide fusidique selon disponibilité suisse ; à vérifier dans l'AIPS)."),
("oral","acuteManagement","décision",3,0,IDSA+" ; "+AIPS,"Des lésions nombreuses, un ecthyma ou une épidémie dans une collectivité justifient un antibiotique oral actif sur S. aureus pendant 7 jours ; la pénicilline suffit si la culture ne trouve que du streptocoque."),
("incision","acuteManagement","décision",3,0,IDSA,"L'incision et le drainage forment le traitement principal de l'abcès, de l'anthrax et du gros furoncle ; un antibiotique seul ne guérit pas une collection."),
("atbabces","acuteManagement","décision",2,0,IDSA,"Après drainage, on n'ajoute un antibiotique qu'en présence d'une réponse systémique, d'une immunodépression marquée ou d'un échec du drainage."),
("manip","chronicManagement","piège",1,0,EXP,"On ne presse jamais un furoncle de la zone centro-faciale, car la manipulation peut propager l'infection vers le sinus caverneux."),
("decolo","chronicManagement","décision",2,0,IDSA,"Devant des abcès récidivants, on draine et cultive tôt, on cherche une cause locale comme un kyste pilonidal ou une hidradénite, puis on discute une décolonisation de 5 jours par mupirocine nasale et lavages à la chlorhexidine."),
("neutro","chronicManagement","terrain particulier",1,0,IDSA,"Des abcès récidivants depuis la petite enfance font rechercher un trouble de la fonction des neutrophiles."),
("gna","hospitalizationComplications","complication",2,0,IDSA,"Un impétigo streptococcique peut se compliquer d'une glomérulonéphrite post-streptococcique, mais pas d'un rhumatisme articulaire aigu ; lors d'une épidémie de glomérulonéphrite, on traite par voie systémique."),
("ssss","hospitalizationComplications","complication",1,0,EXP,"Chez le nourrisson, la toxine exfoliative peut diffuser et provoquer un syndrome d'épidermolyse staphylococcique, qui impose l'hospitalisation."),
("prono","prognosisDischarge","pronostic",1,0,EXP,"L'impétigo guérit en une à deux semaines sans cicatrice, car il reste épidermique."),
("eviction","prognosisDischarge","contexte suisse",1,1,EXP,"Les règles d'éviction des crèches et des écoles relèvent des cantons et des institutions ; en pratique, l'enfant revient quand les lésions sont sèches ou après au moins 24 à 48 heures d'antibiotique efficace."),
("surv","surveillance","examen",1,0,EXP,"Sans amélioration après 48 à 72 heures, on vérifie l'observance et le diagnostic, on cultive et on passe à la voie orale."),
("hyg","followUpNetwork","prévention",2,0,EXP+" ; "+IDSA,"Le lavage des mains, les ongles courts, le linge et les serviettes personnels et la couverture des lésions limitent la transmission dans la famille et la collectivité."),
("resist","followUpNetwork","contexte suisse",1,1,ANR,"En Suisse, anresis.ch surveille l'antibiorésistance ; on adapte toujours le traitement à l'antibiogramme si une culture est faite."),
]
